	'messages:filename-toolong' => 'bn:ফাইলের নাম ২৪০ বাইটের বড় হওয়া যাবে না।',
	'messages:filetype-mime-mismatch' => 'bn:".$1" ফাইল এক্সটেনশনটি MIME থেকে চিহ্নিত ফাইলের ধরনের সাথে মিলছে না ($2)।',
	'messages:filetype-badmime' => 'bn:"$1" MIME ধরনের ফাইল আপলোড করা যাবে না।',
	'messages:filetype-bad-ie-mime' => 'bn:এই ফাইলটি আপলোড করা সম্ভব নয় কারণ ইন্টারনেট এক্সপ্লোরার একে "$1" হিসেবে সনাক্ত করতে পারে, যা অননুমোদিত এবং সম্ভাব্য ক্ষতিকারক ফাইল টাইপ।',
	'messages:filetype-unwanted-type' => 'bn:\'\'\'".$1"\'\'\' ফাইল ধরনটি অগ্রহণযোগ্য।
